-- backend/supabase/migrations/20261109000000_drinks.sql
--
-- DRINKS: a section of their own, separate from food.
--
--   1. recipes.kind  'food' | 'drink'. Meal picks, This or That and the
--                    week plan only ever use kind = 'food'; the Drinks
--                    screen only uses kind = 'drink'.
--   2. recipe_is_drink(name, instructions)
--                    tells a Margarita from a "Fruit Cocktail Cake": a drink
--                    word in the name, no food word, no cooking in the
--                    steps, and at least one drink-making verb. The alcohol
--                    flag alone can't do this (most "alcohol" recipes are
--                    stews with wine in them).
--   3. A trigger classifies imported and community recipes on insert /
--      update; curated rows keep the kind they were inserted with.
--   4. A seed of classic cocktails and mocktails (source 'bitewise'), so
--      the section is good from day one. contains_alcohol is set by the
--      existing age-safeguard trigger, which is what hides cocktails from
--      accounts whose birthday says under 21.

set statement_timeout = 0;

alter table public.recipes
  add column if not exists kind text not null default 'food';

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'recipes_kind_check') then
    alter table public.recipes add constraint recipes_kind_check check (kind in ('food', 'drink'));
  end if;
end $$;

create or replace function public.recipe_is_drink(p_name text, p_instructions text[])
returns boolean
language sql
immutable
as $$
  with t as (
    select lower(coalesce(p_name, '')) as name,
           lower(array_to_string(coalesce(p_instructions, '{}'), ' ')) as steps
  )
  select
    name ~ '\m(margaritas?|mojitos?|martinis?|daiquiris?|sangria|mimosas?|spritzers?|spritz|negroni|bloody mary|mules?|juleps?|coladas?|cosmopolitans?|cosmos?|old fashioned|manhattans?|highballs?|fizz|fizzes|shandy|toddy|eggnog|egg nog|bellinis?|palomas?|caipirinhas?|mai tais?|whiskey sour|whisky sour|amaretto sour|pisco sour|gin sour|vodka sour|hurricanes?|cocktails?|smoothies?|lemonade|limeade|iced tea|sweet tea|lattes?|frappes?|milkshakes?|hot chocolate|hot cocoa|punch|slush|slushie|slushy|coolers?|agua fresca|mocktails?|floats?|horchata|lassi|mulled wine|mulled cider|hot cider|wassail|kombucha|sodas?|nog|cordial|shrub|tonic|chai|cappuccino|espresso|mocha|juice|nectar|cocoa|tea)\M'
    and name !~ '\m(cakes?|pies?|bars?|cookies?|bread|muffins?|pudding|salads?|dips?|sauce|wieners?|sausages?|shrimp|meatballs?|glaze|marinade|chicken|pork|beef|fish|dressing|jello|jell-o|cheesecake|frosting|icing|cupcakes?|brownies?|trifle|fudge|candy|candies|popsicles?|ice cream|sorbet|sherbet|granita|jam|jelly|syrup|crumble|cobbler|fruit cocktail|cocktail wieners|cocktail sauce|cocktail meatballs|cocktail franks|cocktail smokies|roast|ham|turkey|casserole|rolls?|biscuits?|pancakes?|waffles?|scones?|loaf|tart|torte|mousse|custard|truffles?|balls|squares|dessert|parfait|granola|oatmeal|soup|chili|stew|rice|noodles|pasta|wings|ribs|tenderloin|tea cakes?|tea sandwiches|tea ring|punch bowl|concentrate|mix|wedges?|mounds?|canned|canning|cups|cubes|pops|freeze|frozen dessert)\M'
    and steps !~ '\m(bake|baked|baking|oven|preheat|fry|fried|frying|roast|grill|broil|knead|dough|saute|skillet|casserole|degrees)\M'
    and steps ~ '\m(shake|stir|pour|blend|blender|over ice|ice cubes?|glass|glasses|pitcher|strain|muddle|garnish|rim|chill|chilled|crushed ice|cold|refrigerate|float|serve hot|mugs?)\M'
  from t
$$;

-- Imported (kaggle) and community recipes are classified automatically;
-- curated rows say what they are.
create or replace function public.recipes_set_kind()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if new.source in ('kaggle', 'community') then
    new.kind := case when public.recipe_is_drink(new.name, new.instructions) then 'drink' else 'food' end;
  end if;
  return new;
end $$;

drop trigger if exists recipes_set_kind on public.recipes;
create trigger recipes_set_kind
  before insert or update of name, instructions, source on public.recipes
  for each row execute function public.recipes_set_kind();

-- One-time pass over what's already there (a quick word prefilter first,
-- so the full check only runs on candidates).
update public.recipes r
set kind = 'drink'
where r.source in ('kaggle', 'community')
  and r.kind <> 'drink'
  and r.name ~* '\m(margarita|mojito|martini|daiquiri|sangria|mimosa|spritz|negroni|bloody mary|mule|julep|colada|cosmo|old fashioned|manhattan|highball|fizz|shandy|toddy|nog|bellini|paloma|caipirinha|mai tai|sour|hurricane|cocktail|smoothie|lemonade|limeade|tea|latte|frappe|milkshake|hot chocolate|cocoa|punch|slush|cooler|agua fresca|mocktail|float|horchata|lassi|mulled|cider|wassail|kombucha|soda|cordial|shrub|tonic|chai|cappuccino|espresso|mocha|juice|nectar)'
  and public.recipe_is_drink(r.name, r.instructions);

create index if not exists recipes_kind_idx on public.recipes (kind) where kind = 'drink';

